        return $s->database->transaction(function()use($s,$name,$mode,$d,$rows){$encoded=json_encode($d,JSON_THROW_ON_ERROR);$id=$s->insert('target_segments',['name'=>$name,'mode'=>$mode,'definition'=>$encoded,'fingerprint'=>hash('sha256',$encoded),'actor_id'=>get_current_user_id(),'created_at'=>time()]);$seen=[];foreach($rows as $r){if(!$r['eligible']||!$r['source_id']||isset($seen[$r['source_id']]))continue;$seen[$r['source_id']]=true;$s->insert('target_members',['segment_id'=>$id,'source_id'=>$r['source_id'],'payload'=>$s->crypto->seal(['recipient'=>$r['recipient_id'],'campaign'=>$r['campaign_id'],'source_segment'=>$r['source_segment'],'source_id'=>$r['source_id']])]);}return ['id'=>M9Source::OFFSET+$id,'name'=>$name,'count'=>count($seen),'mode'=>$mode];});
